using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using TMPro;
public static class SetupSpeedDisplay {
 static RectTransform Rect(GameObject go,Transform parent,Vector2 anchor,Vector2 pivot,Vector2 position,Vector2 size){var r=go.GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=anchor;r.pivot=pivot;r.anchoredPosition=position;r.sizeDelta=size;return r;}
 static TextMeshProUGUI Label(string name,Transform parent,string text,Vector2 anchor,Vector2 position,Vector2 size,float fontSize,TMP_FontAsset font,TextAlignmentOptions align,Color color){var go=new GameObject(name,typeof(RectTransform),typeof(TextMeshProUGUI));Rect(go,parent,anchor,anchor,position,size);var label=go.GetComponent<TextMeshProUGUI>();label.font=font;label.text=text;label.fontSize=fontSize;label.color=color;label.alignment=align;label.raycastTarget=false;label.textWrappingMode=TextWrappingModes.NoWrap;return label;}
 public static string Main(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(EditorApplication.isPlaying||scene.path!="Assets/Scenes/TestTrackScene.unity")throw new System.Exception("Expected track in Edit mode.");if(GameObject.Find("TestDriveHUD"))throw new System.Exception("HUD already exists.");var car=Object.FindAnyObjectByType<TestDriveMovement>();var font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/Fonts/Nunito/Nunito-Bold SDF.asset");var canvasGO=new GameObject("TestDriveHUD",typeof(RectTransform),typeof(Canvas),typeof(UnityEngine.UI.CanvasScaler));Undo.RegisterCreatedObjectUndo(canvasGO,"Add speed display");var canvas=canvasGO.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=10;var scaler=canvasGO.GetComponent<UnityEngine.UI.CanvasScaler>();scaler.uiScaleMode=UnityEngine.UI.CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);scaler.matchWidthOrHeight=.5f;
 var panel=new GameObject("SpeedPanel",typeof(RectTransform),typeof(UnityEngine.UI.Image));Rect(panel,canvasGO.transform,new Vector2(1,0),new Vector2(1,0),new Vector2(-40,40),new Vector2(240,144));panel.GetComponent<UnityEngine.UI.Image>().color=new Color(.035f,.045f,.06f,.9f);panel.GetComponent<UnityEngine.UI.Image>().raycastTarget=false;
 var accent=new GameObject("Accent",typeof(RectTransform),typeof(UnityEngine.UI.Image));Rect(accent,panel.transform,new Vector2(0,1),new Vector2(0,1),Vector2.zero,new Vector2(240,4));accent.GetComponent<UnityEngine.UI.Image>().color=new Color(.98f,.77f,.25f);accent.GetComponent<UnityEngine.UI.Image>().raycastTarget=false;
 Label("SpeedHeading",panel.transform,"SPEED",new Vector2(0,1),new Vector2(20,-17),new Vector2(120,24),17,font,TextAlignmentOptions.Left,new Color(.75f,.79f,.83f));var digits=Label("SpeedValue",panel.transform,"0",new Vector2(0,0),new Vector2(18,18),new Vector2(148,80),72,font,TextAlignmentOptions.Left,Color.white);Label("SpeedUnit",panel.transform,"km/h",new Vector2(1,0),new Vector2(-18,31),new Vector2(65,28),23,font,TextAlignmentOptions.Right,new Color(.98f,.77f,.25f));
 var display=canvasGO.AddComponent<TestDriveSpeedDisplay>();var so=new SerializedObject(display);so.FindProperty("vehicleBody").objectReferenceValue=car.GetComponent<Rigidbody>();so.FindProperty("speedText").objectReferenceValue=digits;so.ApplyModifiedProperties();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Selection.activeGameObject=panel;return "Saved bottom-right speed display; Rigidbody speed converted to km/h.";
 }
}
